@php
    // Images tirées en direct de l'écosystème Dahomey Discovery pour que
    // chaque card montre un vrai hébergement de la sélection actuelle.
    // Un fallback local reste en place si l'API est momentanément vide.
    $aggregator = app(\App\Services\Aggregator\Aggregator::class);
    $pick = function (string $type, string $fallback) use ($aggregator) {
        $item = $aggregator->accommodations(['accommodation_type' => $type], 1)->first();
        return $item && $item->image ? $item->image : $fallback;
    };
    $imgHotel   = $pick('hotel',       '/assets/img/hotel-640x480.webp');
    $imgVilla   = $pick('villa',       '/assets/img/mangrove-640x480.webp');
    $imgGuest   = $pick('guest-house', '/assets/img/vodun-640x480.webp');
@endphp
